    melting_point = next(i for i, v in enumerate(msd) if v > 10 * msd[0])
except StopIteration:
    melting_point = len(msd) // 2  # Default to halfway if no jump is found

# Calculate diffusion constant (self-diffusivity)
if len(msd) > melting_point:
